{
  "findings": [
    {
      "check_id": "UNKNOWN",
      "title": "Hardcoded database administrator password",
      "resource": "azurerm_mssql_server.changeme_simple_mssql_server",
      "severity": "CRITICAL",
      "explanation": "The SQL administrator password is embedded directly in the Terraform source, exposing it to anyone with repository access and potentially to source-control history. It should be supplied through a sensitive input variable and rotated because the existing value is already disclosed."
    },
    {
      "check_id": "CKV_AZURE_113",
      "title": "Public network access enabled for MSSQL server",
      "resource": "azurerm_mssql_server.changeme_simple_mssql_server",
      "severity": "HIGH",
      "explanation": "The server does not disable public network access, so the Azure SQL public endpoint remains enabled by default. Disabling it reduces exposure and requires database access through private connectivity."
    }
  ],
  "patched_code": "variable \"mssql_administrator_login_password\" {\n  description = \"Administrator password for the MSSQL server. Supply through a secure secret-management mechanism.\"\n  type        = string\n  sensitive   = true\n}\n\nresource \"azurerm_mssql_server\" \"changeme_simple_mssql_server\" {\n  name                          = \"changeme-simple-mssql-database-name\"\n  resource_group_name           = azurerm_resource_group.changeme_simple_mssql_server_resource_group.name\n  location                      = azurerm_resource_group.changeme_simple_mssql_server_resource_group.location\n  version                       = \"12.0\"\n  administrator_login           = \"changemeadmin\"\n  administrator_login_password  = var.mssql_administrator_login_password\n  public_network_access_enabled = false\n}\n",
  "fix_summary": "Replaced the source-embedded administrator password with a required sensitive variable and disabled the MSSQL server's public network endpoint. The exposed password should also be rotated outside Terraform."
}
